   ],
   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\n\n# Task 3: Crop central 32x32 region\nstart_y, end_y = (H - 32) // 2, (H + 32) // 2\nstart_x, end_x = (W - 32) // 2, (W + 32) // 2\ncrop = img[start_y:end_y, start_x:end_x]\n\n# Flip horizontally using slicing\nflipped_h = crop[:, ::-1, :]\n\n# Flip twice\nflipped_twice = flipped_h[:, ::-1, :]\n\n# Check equality\nis_equal = np.array_equal(crop, flipped_twice)\n\nprint(f\"crop shape: {crop.shape}\")\nprint(f\"flipped shape: {flipped_h.shape}\")\nprint(f\"flipping twice returns original: {is_equal}\")"
  },
