   "metadata": {},
   "source": "# Task 4: Intensity Histogram Calculation\nCalculate the 256-bin intensity histogram and find the most frequent gray levels."
  },
  {
   "cell_type": "code",
   "execution_count": 4,
   "id": "a8482bd3",
   "metadata": {
    "execution": {
     "iopub.execute_input": "2026-08-26T16:52:50.384013Z",
