    {
     "name": "stdout",
     "output_type": "stream",
     "text": "Number of non-empty bins: 225\nFive most frequent gray levels and their counts:\n  1. Gray level 111: count = 32\n  2. Gray level 140: count = 31\n  3. Gray level 104: count = 31\n  4. Gray level 162: count = 31\n  5. Gray level 90: count = 31\n"
    }
   ],
   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\nr = img[..., 0]\ng = img[..., 1]\nb = img[..., 2]\ngray = (0.299 * r + 0.587 * g + 0.114 * b).astype(np.uint8)\n\n# Task 4\n# Compute the 256-bin intensity histogram with np.bincount(minlength=256)\nhist = np.bincount(gray.ravel(), minlength=256)\n\n# Number of non-empty bins\nnon_empty_bins = np.count_nonzero(hist)\nprint(f\"Number of non-empty bins: {non_empty_bins}\")\n\n# Five most frequent gray levels with their counts\ntop5_indices = np.argsort(hist)[::-1][:5]\nprint(\"Five most frequent gray levels and their counts:\")\nfor rank, idx in enumerate(top5_indices, 1):\n    print(f\"  {rank}. Gray level {idx}: count = {hist[idx]}\")"
  },
