     "text": "Mean intensity: 126.64\nForeground pixel count: 2053\nForeground ratio: 0.5012\nDownsampled 8x8 ASCII art:\n........\n........\n.......#\n.....###\n...#####\n.#######\n########\n########\n"
    }
   ],
   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\nr = img[..., 0]\ng = img[..., 1]\nb = img[..., 2]\ngray = (0.299 * r + 0.587 * g + 0.114 * b).astype(np.uint8)\n\n# Task 5: Thresholding and ASCII art\nmask = gray > gray.mean()\nfg_count = np.sum(mask)\nfg_ratio = mask.mean()\n\nprint(f\"Mean intensity: {gray.mean():.2f}\")\nprint(f\"Foreground pixel count: {fg_count}\")\nprint(f\"Foreground ratio: {fg_ratio:.4f}\")\n\n# Downsample to 8x8 blocks\n# 64x64 divided into 8x8 blocks of shape 8x8\nblock_h, block_w = H // 8, W // 8\nblocks = mask.reshape(8, block_h, 8, block_w).swapaxes(1, 2) # shape: (8, 8, 8, 8)\nblock_means = blocks.mean(axis=(2, 3))\n\nprint(\"Downsampled 8x8 ASCII art:\")\nfor row in block_means:\n    print(\"\".join('#' if val > 0.5 else '.' for val in row))"
